-- Improve Book 1 rule readability without changing the private verbatim sharh archive.
-- Only public.rules.content is updated; rule_ar, summary, and rule_sources stay intact.

begin;

create temporary table book1_content_replacements (
  lesson_number text not null,
  sort_order integer not null,
  label text not null,
  old_text text not null,
  new_text text not null
) on commit drop;

-- Lesson 6: every Arabic grammatical header is paired with its Russian meaning.
insert into book1_content_replacements values
('6', 3, 'nominal sentence headers',
$old$<th>الْمُبْتَدَأُ</th><th>الْخَبَرُ</th>$old$,
$new$<th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-table-ru">мубтада (подлежащее)</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-table-ru">хабар (сказуемое)</span></th>$new$);

-- Lesson 8: translate the two deliberately incorrect examples and the Arabic meaning labels.
insert into book1_content_replacements values
('8', 1, 'incorrect demonstrative example 1',
$old$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">هٰذَا الرَّجُلُ التَّاجِرُ. ✕</span></div>$old$,
$new$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">هٰذَا الرَّجُلُ التَّاجِرُ. ✕</span><span class="rule-example-ru">Неверно: задуманный смысл — «Этот мужчина — торговец»; хабар должен быть неопределённым: <span dir="rtl" lang="ar">تَاجِرٌ</span>.</span></div>$new$),
('8', 1, 'incorrect demonstrative example 2',
$old$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">ذٰلِكَ الرَّجُلُ الطَّبِيبُ. ✕</span></div>$old$,
$new$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">ذٰلِكَ الرَّجُلُ الطَّبِيبُ. ✕</span><span class="rule-example-ru">Неверно: задуманный смысл — «Тот мужчина — врач»; хабар должен быть неопределённым: <span dir="rtl" lang="ar">طَبِيبٌ</span>.</span></div>$new$),
('8', 4, 'preposition meaning beginning',
$old$<td><span dir="rtl" lang="ar">الْبِدَايَةُ</span></td>$old$,
$new$<td><span class="rule-table-ar" dir="rtl" lang="ar">الْبِدَايَةُ</span><span class="rule-table-ru">начало, исходная точка</span></td>$new$),
('8', 4, 'preposition meaning end',
$old$<td><span dir="rtl" lang="ar">النِّهَايَةُ</span></td>$old$,
$new$<td><span class="rule-table-ar" dir="rtl" lang="ar">النِّهَايَةُ</span><span class="rule-table-ru">конец, конечная точка</span></td>$new$),
('8', 4, 'preposition meaning containment',
$old$<td><span dir="rtl" lang="ar">الظَّرْفِيَّةُ</span></td>$old$,
$new$<td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الظَّرْفِيَّةُ</span><span class="rule-table-ru">нахождение внутри</span></td>$new$),
('8', 4, 'preposition meaning elevation',
$old$<td><span dir="rtl" lang="ar">الِاسْتِعْلَاءُ</span></td>$old$,
$new$<td><span class="rule-table-ar" dir="rtl" lang="ar">الِاسْتِعْلَاءُ</span><span class="rule-table-ru">нахождение сверху</span></td>$new$),
('8', 4, 'preposition meaning possession',
$old$<td><span dir="rtl" lang="ar">الْمِلْكُ</span></td>$old$,
$new$<td><span class="rule-table-ar" dir="rtl" lang="ar">الْمِلْكُ</span><span class="rule-table-ru">принадлежность</span></td>$new$);

-- Lesson 9: pair terms and every incorrect/correct example with a Russian line.
insert into book1_content_replacements values
('9', 1, 'agreement term gender',
$old$<td><span dir="rtl" lang="ar">التَّذْكِيرُ وَالتَّأْنِيثُ</span></td>$old$,
$new$<td><span class="rule-table-ar" dir="rtl" lang="ar">التَّذْكِيرُ وَالتَّأْنِيثُ</span><span class="rule-table-ru">мужской и женский род</span></td>$new$),
('9', 1, 'agreement term definiteness',
$old$<td><span dir="rtl" lang="ar">التَّعْرِيفُ وَالتَّنْكِيرُ</span></td>$old$,
$new$<td><span class="rule-table-ar" dir="rtl" lang="ar">التَّعْرِيفُ وَالتَّنْكِيرُ</span><span class="rule-table-ru">определённость и неопределённость</span></td>$new$),
('9', 1, 'agreement term case',
$old$<td><span dir="rtl" lang="ar">الْإِعْرَابُ</span></td>$old$,
$new$<td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">падежное изменение окончания</span></td>$new$),
('9', 1, 'agreement term singular',
$old$<td><span dir="rtl" lang="ar">الْإِفْرَادُ</span></td>$old$,
$new$<td><span class="rule-table-ar" dir="rtl" lang="ar">الْإِفْرَادُ</span><span class="rule-table-ru">единственное число</span></td>$new$),
('9', 1, 'adjective correction table',
$old$<table><thead><tr><th>Форма, отмеченная в шархе знаком ✕</th><th>Исправленная форма</th><th>Нарушенный признак</th></tr></thead><tbody><tr><td><span dir="rtl" lang="ar">هَذَا الرَّجُلُ كَرِيمٌ طَبِيبٌ</span></td><td><span dir="rtl" lang="ar">هَذَا الرَّجُلُ الْكَرِيمُ طَبِيبٌ</span></td><td>определённость</td></tr><tr><td><span dir="rtl" lang="ar">عَبَّاسٌ تَاجِرٌ الْغَنِيُّ</span></td><td><span dir="rtl" lang="ar">عَبَّاسٌ تَاجِرٌ غَنِيٌّ</span></td><td>неопределённость</td></tr><tr><td><span dir="rtl" lang="ar">الْعَرَبِيَّةُ لُغَةٌ جَمِيلٌ</span></td><td><span dir="rtl" lang="ar">الْعَرَبِيَّةُ لُغَةٌ جَمِيلَةٌ</span></td><td>женский род</td></tr><tr><td><span dir="rtl" lang="ar">لِمَنْ: تِلْكَ السَّيَّارَةُ الْجَدِيدَةِ</span></td><td><span dir="rtl" lang="ar">لِمَنْ تِلْكَ السَّيَّارَةُ الْجَدِيدَةُ؟</span></td><td>падеж</td></tr><tr><td><span dir="rtl" lang="ar">الْمِرْوَحَةُ فِي الْغُرْفَةِ الْكَبِيرُ</span></td><td><span dir="rtl" lang="ar">الْمِرْوَحَةُ فِي الْغُرْفَةِ الْكَبِيرَةِ.</span></td><td>род и падеж</td></tr><tr><td><span dir="rtl" lang="ar">الْكُوبُ لِلْمُدَرِّسِ الْجَدِيدَةِ</span></td><td><span dir="rtl" lang="ar">الْكُوبُ لِلْمُدَرِّسِ الْجَدِيدِ.</span></td><td>род</td></tr></tbody></table>$old$,
$new$<table class="rule-bilingual-table"><thead><tr><th>Форма, отмеченная в шархе знаком ✕</th><th>Исправленная форма</th><th>Нарушенный признак</th></tr></thead><tbody><tr><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">هَذَا الرَّجُلُ كَرِيمٌ طَبِيبٌ</span><span class="rule-table-ru">Задуманный смысл: «Этот благородный мужчина — врач».</span></td><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">هَذَا الرَّجُلُ الْكَرِيمُ طَبِيبٌ</span><span class="rule-table-ru">Этот благородный мужчина — врач.</span></td><td>определённость</td></tr><tr><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">عَبَّاسٌ تَاجِرٌ الْغَنِيُّ</span><span class="rule-table-ru">Задуманный смысл: «Аббас — богатый торговец».</span></td><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">عَبَّاسٌ تَاجِرٌ غَنِيٌّ</span><span class="rule-table-ru">Аббас — богатый торговец.</span></td><td>неопределённость</td></tr><tr><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">الْعَرَبِيَّةُ لُغَةٌ جَمِيلٌ</span><span class="rule-table-ru">Задуманный смысл: «Арабский язык — красивый язык».</span></td><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">الْعَرَبِيَّةُ لُغَةٌ جَمِيلَةٌ</span><span class="rule-table-ru">Арабский язык — красивый язык.</span></td><td>женский род</td></tr><tr><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">لِمَنْ: تِلْكَ السَّيَّارَةُ الْجَدِيدَةِ</span><span class="rule-table-ru">Задуманный смысл: «Кому принадлежит та новая машина?»</span></td><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">لِمَنْ تِلْكَ السَّيَّارَةُ الْجَدِيدَةُ؟</span><span class="rule-table-ru">Кому принадлежит та новая машина?</span></td><td>падеж</td></tr><tr><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">الْمِرْوَحَةُ فِي الْغُرْفَةِ الْكَبِيرُ</span><span class="rule-table-ru">Задуманный смысл: «Вентилятор находится в большой комнате».</span></td><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">الْمِرْوَحَةُ فِي الْغُرْفَةِ الْكَبِيرَةِ.</span><span class="rule-table-ru">Вентилятор находится в большой комнате.</span></td><td>род и падеж</td></tr><tr><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">الْكُوبُ لِلْمُدَرِّسِ الْجَدِيدَةِ</span><span class="rule-table-ru">Задуманный смысл: «Стакан принадлежит новому преподавателю».</span></td><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">الْكُوبُ لِلْمُدَرِّسِ الْجَدِيدِ.</span><span class="rule-table-ru">Стакан принадлежит новому преподавателю.</span></td><td>род</td></tr></tbody></table>$new$),
('9', 2, 'incorrect relative clause 1',
$old$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">مَنِ الْوَلَدُ الصَّغِيرُ خَرَجَ؟ ✕</span></div>$old$,
$new$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">مَنِ الْوَلَدُ الصَّغِيرُ خَرَجَ؟ ✕</span><span class="rule-example-ru">Неверно: «Кто тот маленький мальчик, который вышел?» — пропущено относительное имя <span dir="rtl" lang="ar">الَّذِي</span>.</span></div>$new$),
('9', 2, 'incorrect relative clause 2',
$old$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">الْكِتَابُ عَلَى الْمَكْتَبِ لِلْمُدَرِّسِ. ✕</span></div>$old$,
$new$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">الْكِتَابُ عَلَى الْمَكْتَبِ لِلْمُدَرِّسِ. ✕</span><span class="rule-example-ru">Неверно для задуманной связи: «Книга, которая лежит на столе, принадлежит преподавателю» — нужно <span dir="rtl" lang="ar">الَّذِي</span>.</span></div>$new$),
('9', 2, 'incorrect relative clause 3',
$old$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">لِمَنِ الْقَلَمُ عَلَى الْمَكْتَبِ. ✕</span></div>$old$,
$new$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">لِمَنِ الْقَلَمُ عَلَى الْمَكْتَبِ. ✕</span><span class="rule-example-ru">Неверно: «Кому принадлежит ручка, которая лежит на столе?» — нужны <span dir="rtl" lang="ar">الَّذِي</span> и вопросительный знак.</span></div>$new$);

-- Lesson 10: translate both sides of comparison tables and the name forms.
insert into book1_content_replacements values
('10', 2, 'possession choice table',
$old$<table><thead><tr><th>Отмечено ✓</th><th>Отмечено ✕</th></tr></thead><tbody><tr><td><span dir="rtl" lang="ar">أَلَكَ أَخٌ؟</span></td><td><span dir="rtl" lang="ar">أَعِنْدَكَ أَخٌ؟</span></td></tr><tr><td><span dir="rtl" lang="ar">أَعِنْدَكَ كِتَابٌ؟</span></td><td><span dir="rtl" lang="ar">أَلَكَ كِتَابٌ؟</span></td></tr></tbody></table>$old$,
$new$<table class="rule-bilingual-table"><thead><tr><th>Отмечено ✓</th><th>Отмечено ✕</th></tr></thead><tbody><tr><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">أَلَكَ أَخٌ؟</span><span class="rule-table-ru">У тебя есть брат?</span></td><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">أَعِنْدَكَ أَخٌ؟</span><span class="rule-table-ru">Тот же задуманный смысл; для родства здесь неверно выбрано <span dir="rtl" lang="ar">عِنْدَ</span>.</span></td></tr><tr><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">أَعِنْدَكَ كِتَابٌ؟</span><span class="rule-table-ru">У тебя есть книга?</span></td><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">أَلَكَ كِتَابٌ؟</span><span class="rule-table-ru">Тот же задуманный смысл; для временного обладания здесь неверно выбрано <span dir="rtl" lang="ar">لِـ</span>.</span></td></tr></tbody></table>$new$),
('10', 3, 'with comparison table',
$old$<table><thead><tr><th>Отмечено ✓</th><th>Отмечено ✕</th><th>Что проверяется</th></tr></thead><tbody><tr><td><span dir="rtl" lang="ar">مَعَ خَالِدٍ</span></td><td><span dir="rtl" lang="ar">مَعَ خَالِدٌ</span></td><td><span dir="rtl" lang="ar">جَرٌّ</span> после <span dir="rtl" lang="ar">مَعَ</span></td></tr><tr><td><span dir="rtl" lang="ar">عَائِشَةُ مَعَهَا زَوْجُهَا</span></td><td><span dir="rtl" lang="ar">عَائِشَةُ مَعَهُ زَوْجُهَا</span></td><td>женский суффикс <span dir="rtl" lang="ar">ـهَا</span></td></tr><tr><td><span dir="rtl" lang="ar">مَنْ مَعَكَ يَا عَلِيُّ؟ مَعِي زَمِيلِي</span></td><td><span dir="rtl" lang="ar">مَنْ مَعَكَ يَا عَلِيُّ؟ مَعَكَ زَمِيلِي</span></td><td>в ответе нужен суффикс говорящего <span dir="rtl" lang="ar">ـِي</span></td></tr></tbody></table>$old$,
$new$<table class="rule-bilingual-table"><thead><tr><th>Отмечено ✓</th><th>Отмечено ✕</th><th>Что проверяется</th></tr></thead><tbody><tr><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">مَعَ خَالِدٍ</span><span class="rule-table-ru">вместе с Халидом</span></td><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">مَعَ خَالِدٌ</span><span class="rule-table-ru">Задумано: «вместе с Халидом»; окончание неверно.</span></td><td><span dir="rtl" lang="ar">جَرٌّ</span> — родительный падеж после <span dir="rtl" lang="ar">مَعَ</span></td></tr><tr><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">عَائِشَةُ مَعَهَا زَوْجُهَا</span><span class="rule-table-ru">Вместе с Аишей — её муж.</span></td><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">عَائِشَةُ مَعَهُ زَوْجُهَا</span><span class="rule-table-ru">Тот же задуманный смысл; местоимение ошибочно поставлено в мужском роде.</span></td><td>женский суффикс <span dir="rtl" lang="ar">ـهَا</span> — «с ней»</td></tr><tr><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">مَنْ مَعَكَ يَا عَلِيُّ؟ مَعِي زَمِيلِي</span><span class="rule-table-ru">Кто с тобой, Али? Со мной мой товарищ.</span></td><td><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">مَنْ مَعَكَ يَا عَلِيُّ؟ مَعَكَ زَمِيلِي</span><span class="rule-table-ru">В ответе ошибочно повторено «с тобой» вместо «со мной».</span></td><td>в ответе нужен суффикс говорящего <span dir="rtl" lang="ar">ـِي</span> — «со мной»</td></tr></tbody></table>$new$),
('10', 4, 'masculine names table',
$old$<table><thead><tr><th>Обычное мужское имя</th><th>Мужское имя на ة без танвина</th></tr></thead><tbody><tr><td><span dir="rtl" lang="ar">مُحَمَّدٌ</span></td><td><span dir="rtl" lang="ar">حَمْزَةُ</span></td></tr><tr><td><span dir="rtl" lang="ar">خَالِدٌ</span></td><td><span dir="rtl" lang="ar">طَلْحَةُ</span></td></tr><tr><td><span dir="rtl" lang="ar">مَحْمُودٌ</span></td><td><span dir="rtl" lang="ar">مُعَاوِيَةُ</span></td></tr><tr><td><span dir="rtl" lang="ar">حُسَيْنٌ</span></td><td><span dir="rtl" lang="ar">أُسَامَةُ</span></td></tr></tbody></table>$old$,
$new$<table class="rule-bilingual-table"><thead><tr><th>Обычное мужское имя</th><th>Мужское имя на <span dir="rtl" lang="ar">ة</span> без танвина</th></tr></thead><tbody><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">مُحَمَّدٌ</span><span class="rule-table-ru">Мухаммад</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">حَمْزَةُ</span><span class="rule-table-ru">Хамза</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">خَالِدٌ</span><span class="rule-table-ru">Халид</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">طَلْحَةُ</span><span class="rule-table-ru">Тальха</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">مَحْمُودٌ</span><span class="rule-table-ru">Махмуд</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">مُعَاوِيَةُ</span><span class="rule-table-ru">Муавия</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">حُسَيْنٌ</span><span class="rule-table-ru">Хусейн</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">أُسَامَةُ</span><span class="rule-table-ru">Усама</span></td></tr></tbody></table>$new$),
('10', 4, 'hamza tanwin example',
$old$<div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">حَمْزَةُ ✓　حَمْزَةٌ ✕</span></div>$old$,
$new$<div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">حَمْزَةُ ✓　حَمْزَةٌ ✕</span><span class="rule-example-ru">Имя Хамза: форма с даммой верна; форма с танвином неверна.</span></div>$new$),
