$new$<table class="rule-bilingual-table"><thead><tr><th>Единственное</th><th>Множественное</th></tr></thead><tbody><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">أَنَا مُدَرِّسٌ</span><span class="rule-table-ru">Я преподаватель.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">نَحْنُ مُدَرِّسُونَ</span><span class="rule-table-ru">Мы преподаватели.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">أَنَا مُدَرِّسَةٌ</span><span class="rule-table-ru">Я преподавательница.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">نَحْنُ مُدَرِّسَاتٌ</span><span class="rule-table-ru">Мы преподавательницы.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">أَنْتَ طَبِيبٌ</span><span class="rule-table-ru">Ты врач — обращение к мужчине.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">أَنْتُمْ أَطِبَّاءُ</span><span class="rule-table-ru">Вы врачи — обращение к мужчинам.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">أَنْتِ طَبِيبَةٌ</span><span class="rule-table-ru">Ты врач — обращение к женщине.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">أَنْتُنَّ طَبِيبَاتٌ</span><span class="rule-table-ru">Вы врачи — обращение к женщинам.</span></td></tr></tbody></table>$new$),
