('21', 1, 'review syntax table',
$old$<table><thead><tr><th>Предложение</th><th>Синтаксическая структура</th></tr></thead><tbody><tr><td><span dir="rtl" lang="ar">أَبْوَابُهَا</span></td><td><span dir="rtl" lang="ar">أَبْوَابُ — مُضَافٌ؛ ـهَا — مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">فَصْلُنَا</span></td><td><span dir="rtl" lang="ar">فَصْلُ — مُضَافٌ؛ ـنَا — مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">هَذِهِ مَدْرَسَتِي</span></td><td><span dir="rtl" lang="ar">هَذِهِ — مُبْتَدَأٌ؛ مَدْرَسَتِي — خَبَرٌ، وَهِيَ مُضَافٌ وَالْيَاءُ مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">ذَاكَ كُرْسِيُّهُ</span></td><td><span dir="rtl" lang="ar">ذَاكَ — مُبْتَدَأٌ؛ كُرْسِيُّهُ — خَبَرٌ، وَهُوَ مُضَافٌ وَالْهَاءُ مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">مَكْتَبُ الْمُدَرِّسِ كَبِيرٌ</span></td><td><span dir="rtl" lang="ar">مَكْتَبُ — مُبْتَدَأٌ وَمُضَافٌ؛ الْمُدَرِّسِ — مُضَافٌ إِلَيْهِ؛ كَبِيرٌ — خَبَرٌ</span></td></tr><tr><td><span dir="rtl" lang="ar">لُغَاتُهُمْ مُخْتَلِفَةٌ</span></td><td><span dir="rtl" lang="ar">لُغَاتُهُمْ — مُبْتَدَأٌ، وَهُوَ مُضَافٌ وَهُمْ مُضَافٌ إِلَيْهِ؛ مُخْتَلِفَةٌ — خَبَرٌ</span></td></tr><tr><td><span dir="rtl" lang="ar">هِيَ مَدْرَسَةٌ كَبِيرَةٌ</span></td><td><span dir="rtl" lang="ar">هِيَ — مُبْتَدَأٌ؛ مَدْرَسَةٌ — خَبَرٌ؛ كَبِيرَةٌ — نَعْتٌ</span></td></tr></tbody></table>$old$,
$new$<table class="rule-bilingual-table"><thead><tr><th>Предложение</th><th>Синтаксическая структура</th></tr></thead><tbody><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">أَبْوَابُهَا</span><span class="rule-table-ru">её двери</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَبْوَابُ — مُضَافٌ؛ ـهَا — مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru"><span dir="rtl" lang="ar">أَبْوَابُ</span> — мудаф (первый член идафы); <span dir="rtl" lang="ar">ـهَا</span> — мудаф иляйхи (второй член идафы).</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">فَصْلُنَا</span><span class="rule-table-ru">наш класс</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَصْلُ — مُضَافٌ؛ ـنَا — مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru"><span dir="rtl" lang="ar">فَصْلُ</span> — мудаф; <span dir="rtl" lang="ar">ـنَا</span> — мудаф иляйхи.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">هَذِهِ مَدْرَسَتِي</span><span class="rule-table-ru">Это моя школа.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">هَذِهِ — مُبْتَدَأٌ؛ مَدْرَسَتِي — خَبَرٌ، وَهِيَ مُضَافٌ وَالْيَاءُ مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru"><span dir="rtl" lang="ar">هَذِهِ</span> — мубтада; <span dir="rtl" lang="ar">مَدْرَسَتِي</span> — хабар и мудаф; <span dir="rtl" lang="ar">ـِي</span> — мудаф иляйхи.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">ذَاكَ كُرْسِيُّهُ</span><span class="rule-table-ru">То — его стул.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">ذَاكَ — مُبْتَدَأٌ؛ كُرْسِيُّهُ — خَبَرٌ، وَهُوَ مُضَافٌ وَالْهَاءُ مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru"><span dir="rtl" lang="ar">ذَاكَ</span> — мубтада; <span dir="rtl" lang="ar">كُرْسِيُّهُ</span> — хабар и мудаф; <span dir="rtl" lang="ar">ـهُ</span> — мудаф иляйхи.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">مَكْتَبُ الْمُدَرِّسِ كَبِيرٌ</span><span class="rule-table-ru">Стол преподавателя большой.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">مَكْتَبُ — مُبْتَدَأٌ وَمُضَافٌ؛ الْمُدَرِّسِ — مُضَافٌ إِلَيْهِ؛ كَبِيرٌ — خَبَرٌ</span><span class="rule-table-ru"><span dir="rtl" lang="ar">مَكْتَبُ</span> — мубтада и мудаф; <span dir="rtl" lang="ar">الْمُدَرِّسِ</span> — мудаф иляйхи; <span dir="rtl" lang="ar">كَبِيرٌ</span> — хабар.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">لُغَاتُهُمْ مُخْتَلِفَةٌ</span><span class="rule-table-ru">Их языки различны.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">لُغَاتُهُمْ — مُبْتَدَأٌ، وَهُوَ مُضَافٌ وَهُمْ مُضَافٌ إِلَيْهِ؛ مُخْتَلِفَةٌ — خَبَرٌ</span><span class="rule-table-ru"><span dir="rtl" lang="ar">لُغَاتُهُمْ</span> — мубтада и мудаф; <span dir="rtl" lang="ar">ـهُمْ</span> — мудаф иляйхи; <span dir="rtl" lang="ar">مُخْتَلِفَةٌ</span> — хабар.</span></td></tr><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">هِيَ مَدْرَسَةٌ كَبِيرَةٌ</span><span class="rule-table-ru">Она — большая школа.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">هِيَ — مُبْتَدَأٌ؛ مَدْرَسَةٌ — خَبَرٌ؛ كَبِيرَةٌ — نَعْتٌ</span><span class="rule-table-ru"><span dir="rtl" lang="ar">هِيَ</span> — мубтада; <span dir="rtl" lang="ar">مَدْرَسَةٌ</span> — хабар; <span dir="rtl" lang="ar">كَبِيرَةٌ</span> — на‘т (согласованное определение).</span></td></tr></tbody></table>$new$);

