$new$<table class="rule-bilingual-table"><thead><tr><th>№</th><th>Вид</th><th>Примеры автора</th><th>Русский смысл вида</th></tr></thead><tbody><tr><td>1</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الْعَلَمُ الْمُؤَنَّثُ</span><span class="rule-table-ru">женское собственное имя</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">مَرْيَمُ، زَيْنَبُ، عَائِشَةُ، مَكَّةُ، جُدَّةُ</span><span class="rule-table-ru">Марьям, Зайнаб, Аиша, Мекка, Джидда</span></td><td>женское собственное имя</td></tr><tr><td>2</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الْعَلَمُ الْمُؤَنَّثُ فِي اللَّفْظِ، وَمَعْنَاهُ مُذَكَّرٌ</span><span class="rule-table-ru">собственное имя, женское по форме, но мужское по значению</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">حَمْزَةُ، مُعَاوِيَةُ، طَلْحَةُ</span><span class="rule-table-ru">Хамза, Муавия, Тальха</span></td><td>собственное имя, женское по форме, но мужское по значению</td></tr><tr><td>3</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الْعَلَمُ الْمَخْتُومُ بِأَلِفٍ وَنُونٍ زَائِدَتَيْنِ</span><span class="rule-table-ru">собственное имя с добавочными алифом и нуном в конце</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">عُثْمَانُ، عَفَّانُ، سُفْيَانُ، مَرْوَانُ، رَمَضَانُ</span><span class="rule-table-ru">Усман, Аффан, Суфьян, Марван, Рамадан</span></td><td>собственное имя с добавочными алифом и нуном в конце</td></tr><tr><td>4</td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْعَلَمُ الَّذِي عَلَى وَزْنِ الْفِعْلِ</span><span class="rule-table-ru">собственное имя по модели глагола</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">أَحْمَدُ، أَنْوَرُ، يَزِيدُ</span><span class="rule-table-ru">Ахмад, Анвар, Язид</span></td><td>собственное имя по модели глагола</td></tr><tr><td>5</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الْعَلَمُ الْأَعْجَمِيُّ</span><span class="rule-table-ru">иноязычное собственное имя</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">إِبْرَاهِيمُ، يَعْقُوبُ، وَلِيَمُ، إِدْوَرْدُ، بَاكِسْتَانُ، بَارِيسُ</span><span class="rule-table-ru">Ибрахим, Якуб, Уильям, Эдвард, Пакистан, Париж</span></td><td>иноязычное собственное имя</td></tr><tr><td>6</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الصِّفَةُ الَّتِي عَلَى وَزْنِ أَفْعَلَ</span><span class="rule-table-ru">прилагательное по модели <span dir="rtl" lang="ar">أَفْعَلُ</span></span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">أَبْيَضُ، أَحْمَرُ، أَخْضَرُ</span><span class="rule-table-ru">белый, красный, зелёный</span></td><td>прилагательное по модели <span dir="rtl" lang="ar">أَفْعَلُ</span></td></tr><tr><td>7</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الصِّفَةُ الَّتِي عَلَى وَزْنِ فَعْلَانَ</span><span class="rule-table-ru">прилагательное по модели <span dir="rtl" lang="ar">فَعْلَانُ</span></span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">كَسْلَانُ، جَوْعَانُ، عَطْشَانُ، غَضْبَانُ</span><span class="rule-table-ru">ленивый, голодный, испытывающий жажду, разгневанный</span></td><td>прилагательное по модели <span dir="rtl" lang="ar">فَعْلَانُ</span></td></tr><tr><td>8</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الِاسْمُ الْمَخْتُومُ بِأَلِفٍ مَمْدُودَةٍ عَلَى وَزْنِ أَفْعِلَاءَ</span><span class="rule-table-ru">имя с длинным алифом и хамзой в конце по модели <span dir="rtl" lang="ar">أَفْعِلَاءُ</span></span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">أَغْنِيَاءُ، أَصْدِقَاءُ، أَطِبَّاءُ، أَقْوِيَاءُ</span><span class="rule-table-ru">богатые, друзья, врачи, сильные</span></td><td>имя с длинным алифом и хамзой в конце по модели <span dir="rtl" lang="ar">أَفْعِلَاءُ</span></td></tr><tr><td>9</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الِاسْمُ الْمَخْتُومُ بِأَلِفٍ مَمْدُودَةٍ عَلَى وَزْنِ فُعَلَاءَ</span><span class="rule-table-ru">имя с длинным алифом и хамзой в конце по модели <span dir="rtl" lang="ar">فُعَلَاءُ</span></span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">فُقَرَاءُ، وُزَرَاءُ، زُمَلَاءُ، عُلَمَاءُ</span><span class="rule-table-ru">бедные, министры, товарищи, учёные</span></td><td>имя с длинным алифом и хамзой в конце по модели <span dir="rtl" lang="ar">فُعَلَاءُ</span></td></tr><tr><td>10</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الِاسْمُ الَّذِي عَلَى وَزْنِ مَفَاعِلَ</span><span class="rule-table-ru">имя по модели <span dir="rtl" lang="ar">مَفَاعِلُ</span></span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">مَسَاجِدُ، مَعَاهِدُ، فَنَادِقُ، مَكَاتِبُ</span><span class="rule-table-ru">мечети, институты, гостиницы, письменные столы / кабинеты</span></td><td>имя по модели <span dir="rtl" lang="ar">مَفَاعِلُ</span></td></tr><tr><td>11</td><td><span class="rule-table-ar" dir="rtl" lang="ar">الِاسْمُ الَّذِي عَلَى وَزْنِ مَفَاعِيلَ</span><span class="rule-table-ru">имя по модели <span dir="rtl" lang="ar">مَفَاعِيلُ</span></span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">مَنَادِيلُ، مَفَاتِيحُ، فَنَاجِينُ، كَرَاسِيُّ</span><span class="rule-table-ru">платки, ключи, чашки, стулья</span></td><td>имя по модели <span dir="rtl" lang="ar">مَفَاعِيلُ</span></td></tr></tbody></table>$new$),
