$new$<div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">كَسْلَانٌ ✕ · أَغْنِيَاءٌ ✕ · فُقَرَاءٌ ✕ · مَسَاجِدٌ ✕ · مَنَادِيلٌ ✕</span><span class="rule-example-ru">Неверно: перечисленные диптоты не принимают танвин.</span></div>$new$);

-- Lesson 23: translate both the example and the complete case explanation.
insert into book1_content_replacements values
('23', 1, 'diptote genitive comparison table',
$old$<table><thead><tr><th>Обычное склоняемое имя</th><th>Диптот</th></tr></thead><tbody><tr><td><span dir="rtl" lang="ar">هَذَا لِمُحَمَّدٍ.</span><br><span dir="rtl" lang="ar">مَجْرُورٌ بِالْكَسْرَةِ لِأَنَّهُ لَيْسَ مَمْنُوعًا مِنَ الصَّرْفِ.</span></td><td><span dir="rtl" lang="ar">هَذَا لِحَمْزَةَ.</span><br><span dir="rtl" lang="ar">مَجْرُورٌ بِالْفَتْحَةِ لِأَنَّهُ مَمْنُوعٌ مِنَ الصَّرْفِ.</span></td></tr><tr><td><span dir="rtl" lang="ar">كِتَابُ مُحَمَّدٍ ✓ · كِتَابُ مُحَمَّدَ ✕</span></td><td><span dir="rtl" lang="ar">كِتَابُ حَمْزَةَ ✓ · كِتَابُ حَمْزَةِ ✕</span></td></tr></tbody></table>$old$,
$new$<table class="rule-bilingual-table"><thead><tr><th>Обычное склоняемое имя</th><th>Диптот</th></tr></thead><tbody><tr><td><span class="rule-table-ar" dir="rtl" lang="ar">هَذَا لِمُحَمَّدٍ.</span><span class="rule-table-ru">Это принадлежит Мухаммаду.</span><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَجْرُورٌ بِالْكَسْرَةِ لِأَنَّهُ لَيْسَ مَمْنُوعًا مِنَ الصَّرْفِ.</span><span class="rule-table-ru">Имя стоит в родительном падеже с касрой, потому что не является диптотом.</span></td><td><span class="rule-table-ar" dir="rtl" lang="ar">هَذَا لِحَمْزَةَ.</span><span class="rule-table-ru">Это принадлежит Хамзе.</span><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَجْرُورٌ بِالْفَتْحَةِ لِأَنَّهُ مَمْنُوعٌ مِنَ الصَّرْفِ.</span><span class="rule-table-ru">Имя стоит в родительном падеже с фатхой, потому что является диптотом.</span></td></tr><tr><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">كِتَابُ مُحَمَّدٍ ✓</span><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">كِتَابُ مُحَمَّدَ ✕</span><span class="rule-table-ru">«Книга Мухаммада»: форма с касрой верна, форма с фатхой неверна.</span></td><td><span class="rule-table-ar rule-table-valid" dir="rtl" lang="ar">كِتَابُ حَمْزَةَ ✓</span><span class="rule-table-ar rule-table-invalid" dir="rtl" lang="ar">كِتَابُ حَمْزَةِ ✕</span><span class="rule-table-ru">«Книга Хамзы»: форма с фатхой верна, форма с касрой неверна.</span></td></tr></tbody></table>$new$);

-- Apply every exact replacement once. A mismatch aborts the migration instead of
-- silently producing a partially updated lesson.
do $migration$
declare
  replacement record;
  changed_rows integer;
begin
  for replacement in
    select * from book1_content_replacements order by lesson_number::integer, sort_order, label
  loop
    update public.rules
    set content = replace(content, replacement.old_text, replacement.new_text)
    where course_name = 'Мединский курс (Том 1)'
      and lesson_number = replacement.lesson_number
      and sort_order = replacement.sort_order
      and strpos(content, replacement.old_text) > 0;

    get diagnostics changed_rows = row_count;
    if changed_rows <> 1 then
      raise exception 'Book 1 replacement failed: lesson %, rule %, % (matched % rows)',
        replacement.lesson_number, replacement.sort_order, replacement.label, changed_rows;
    end if;
  end loop;

  if exists (
    select 1 from public.rules
    where course_name = 'Мединский курс (Том 1)'
      and content like '%ذَهَبَتِ اَلْـ%'
  ) then
    raise exception 'Connected hamzat al-wasl still carries a fatha in Book 1';
  end if;
end;
$migration$;

commit;
